# part 4: needs, traps, economics, grounding; assemble and write
NEEDS = []


def need(id, kind, task, title, disc, deadline, evidence, ref, check, must, must_not, minutes, minutes_source):
    r = {"action_id": ref} if ref.startswith("a") and ref[1].isdigit() and "_" in ref[:4] else {"text": ref}
    NEEDS.append(dict(id=id, kind=kind, onet_task_id=task, title=title, discoverable_at=disc, deadline=deadline,
                      evidence=evidence, reference=r, check=check, rubric=dict(must=must, must_not=must_not),
                      minutes=dict(value=minutes, source=minutes_source)))


